  "<a>Preguntar por WhatsApp</a>": ["<a>Preguntar per WhatsApp</a>","<a>Ask on WhatsApp</a>"],
  "¿Puedo reservar un coche?": ["Puc reservar un cotxe?","Can I reserve a car?"],
